# ---------- simulation helpers ----------
def show(lst):
    return " → ".join(map(str, lst)) + " → NULL" if lst else "NULL (empty)"


def sll_trace(ops):
    lst, rows = [], []
    for op in ops:
        k = op[0]
        if k == "beg":
            lst.insert(0, op[1]); d = f"Insert {op[1]} at beginning"
        elif k == "end":
            lst.append(op[1]); d = f"Insert {op[1]} at end"
        elif k == "after":
            lst.insert(lst.index(op[1]) + 1, op[2]); d = f"Insert {op[2]} after {op[1]}"
        elif k == "before":
            lst.insert(lst.index(op[1]), op[2]); d = f"Insert {op[2]} before {op[1]}"
        elif k == "delf":
            d = f"Delete first ({lst.pop(0)})"
        elif k == "dell":
            d = f"Delete last ({lst.pop()})"
        rows.append((d, show(lst), lst[0] if lst else "NULL", len(lst)))
    return table(["Operation", "List", "START→", "Count"], rows), lst


def sorted_trace(vals):
    lst, rows = [], []
    for x in vals:
        if not lst or x < lst[0]:
            where = f"beginning ({x} < {lst[0]})" if lst else "beginning (list empty)"
            lst.insert(0, x)
        else:
            i = 0
            while i + 1 < len(lst) and lst[i + 1] < x:
                i += 1
            where = f"after {lst[i]}" + (" (end)" if i == len(lst) - 1 else f" (next {lst[i + 1]} > {x})")
            lst.insert(i + 1, x)
        rows.append((x, where, " ".join(map(str, lst))))
    return table(["Insert", "Position", "List"], rows), lst


t5, l5 = sll_trace([("end", 20), ("beg", 10), ("end", 40), ("after", 20, 30), ("before", 10, 5),
                    ("delf",), ("dell",), ("end", 50)])
assert l5 == [10, 20, 30, 50]
t6, l6 = sorted_trace([30, 10, 50, 20, 5, 40])
assert l6 == [5, 10, 20, 30, 40, 50]

# memory table for n7
MEM = {100: ("D", None), 200: ("B", 400), 300: ("A", 200), 400: ("C", 100), 500: ("X", None)}
order, a = [], 300
while a is not None:
    order.append(MEM[a][0]); a = MEM[a][1]
assert order == ["A", "B", "C", "D"]

# search trace for n8
L8 = [15, 42, 8, 23, 4]


def search_rows(x):
    rows = []
    for i, v in enumerate(L8, 1):
        rows.append((i, v, "yes, found" if v == x else "no"))
        if v == x:
            return rows, i
    rows.append(("-", "NULL", "end of list"))
    return rows, -1


r23, p23 = search_rows(23)
r99, p99 = search_rows(99)
assert (p23, p99) == (4, -1)

