        VE("What do & and * do?", "& gives the address of a variable; * gives the value stored at the address held by a pointer."),
        VE("What is a NULL pointer?", "A pointer that does not point to any valid memory (value NULL). The last node of a list has next = NULL."),
        VE("If int *p holds 1000, what is p + 1?", "1004, because p + 1 moves by sizeof(int) = 4 bytes."),
        VE("What is a structure?", "A user-defined data type that groups members of different data types under one name."),
        VE("Difference between . and -> ?", "The dot operator accesses members through a structure variable; the arrow operator through a structure pointer."),
        VE("What is a self-referential structure?", "A structure that contains a pointer to a structure of the same type, e.g. a linked list node."),
        VE("What is dynamic memory allocation?", "Allocating memory at run time from the heap using malloc, calloc and realloc, and releasing it with free."),
        VE("Difference between malloc and calloc?", "malloc takes one argument and leaves garbage values; calloc takes two arguments and initialises memory to 0."),
        VE("What does malloc return if memory is not available?", "NULL."),
        VE("What is a memory leak?", "Memory allocated dynamically that is never freed."),
        VE("What is a dangling pointer?", "A pointer that still holds the address of memory that has been freed."),
